package in.openmiraie.android;

import org.json.*;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class SwingTest {
    static Profile profile()throws Exception{
        JSONObject model=new JSONObject(ProtocolTest.profile().raw.toString()).put("modelId","140013");
        for(String[] axis:new String[][]{{Swing.VERTICAL,"acvs"},{Swing.HORIZONTAL,"achs"}})model.getJSONArray("controlCapabilities").put(new JSONObject().put("capability",axis[0]).put("attributes",new JSONArray().put(new JSONObject().put("key",axis[1]).put("range",range(0,5,1)))));
        return new Profile(model,new JSONObject("{category:'AC',modelId:'140013'}"));
    }
    static JSONObject range(int min,int max,int step)throws Exception{return new JSONObject().put("min",new JSONArray().put(new JSONObject().put("value",min))).put("max",new JSONArray().put(new JSONObject().put("value",max))).put("increment",new JSONArray().put(new JSONObject().put("value",step)));}
    static JSONObject state()throws Exception{return ProtocolTest.state().put("acvs",1).put("achs",1);}
    static void rejects(Profile p,JSONObject state,String cap,Object code)throws Exception{try{p.command(cap,code,state);fail("Must reject unsupported swing input");}catch(IllegalArgumentException expected){}}
    static final class Fake implements CommandRunner.Port{
        JSONObject state;List<Profile.Command> sent=new ArrayList<>();int reads,saved;boolean match=true,failSend,failRead,expire,offline,cleaning;
        Fake()throws Exception{state=SwingTest.state();}
        public void send(Profile.Command command)throws Exception{sent.add(command);if(failSend)throw new java.io.IOException();if(match)state.put(command.key(),command.value());}
        public JSONObject read()throws Exception{reads++;if(expire)throw new Api.Expired();if(failRead)throw new java.io.IOException();JSONObject result=new JSONObject(state.toString());if(offline)result.put("onlineStatus",false);if(cleaning)result.put("acec","on");return result;}
        public void observed(JSONObject observed){saved++;}
    }
    static CommandRunner runner(Fake f,List<Long> waits,List<String> progress){return new CommandRunner(f,waits::add,progress::add);}
    @Test public void allCodesUseIntegerModelKeysAndIndependentIndexes()throws Exception{
        for(String cap:new String[]{Swing.VERTICAL,Swing.HORIZONTAL})for(int code=0;code<=5;code++){Profile p=profile();Profile.Command c=p.command(cap,code,state());JSONObject wire=c.params();String key=cap.equals(Swing.VERTICAL)?"acvs":"achs";assertEquals(key,c.key());assertEquals(cap.equals(Swing.VERTICAL)?5:6,c.index());assertTrue(wire.get(key) instanceof Integer);assertEquals(code,wire.getInt(key));assertEquals("an",wire.getString("cnt"));assertEquals("0",wire.getString("sid"));assertEquals(4,wire.length());assertFalse(wire.has(cap.equals(Swing.VERTICAL)?"achs":"acvs"));}
    }
    @Test public void actualModelKeyOverridesShortKeyAssumption()throws Exception{Profile p=profile();p.attribute(Swing.VERTICAL).put("key","custom_vertical");JSONObject s=state().put("custom_vertical",1);Profile.Command c=p.command(Swing.VERTICAL,2,s);assertEquals("custom_vertical",c.key());assertEquals(2,c.params().getInt("custom_vertical"));assertFalse(c.params().has("acvs"));}
    @Test public void missingMetadataNeverInventsDefaultPositions()throws Exception{Profile p=profile();p.attribute(Swing.VERTICAL).remove("range");assertTrue(Swing.positions(p,Swing.VERTICAL).isEmpty());assertFalse(p.supports(Swing.VERTICAL));rejects(p,state(),Swing.VERTICAL,0);assertEquals(List.of(0,1,2,3,4,5),Swing.positions(p,Swing.HORIZONTAL));}
    @Test public void narrowerRangeAndStepAreRespected()throws Exception{Profile p=profile();p.attribute(Swing.VERTICAL).put("range",range(1,5,2));assertEquals(List.of(1,3,5),Swing.positions(p,Swing.VERTICAL));rejects(p,state(),Swing.VERTICAL,2);assertEquals(3,p.command(Swing.VERTICAL,3,state()).value());}
    @Test public void explicitListIsNotWidenedAndConflictingRangeFailsClosed()throws Exception{Profile p=profile();JSONObject a=p.attribute(Swing.HORIZONTAL);a.remove("range");a.put("intValues",new JSONArray("[5,0]"));assertEquals(List.of(0,5),Swing.positions(p,Swing.HORIZONTAL));assertFalse(p.blocked(state(),Swing.HORIZONTAL).isEmpty());JSONObject current=state().put("achs",0);rejects(p,current,Swing.HORIZONTAL,3);assertEquals(5,p.command(Swing.HORIZONTAL,5,current).value());a.put("range",range(1,5,1));assertTrue(Swing.positions(p,Swing.HORIZONTAL).isEmpty());}
    @Test public void malformedMetadataFailsClosed()throws Exception{
        String[] shapes={"{}","{range:null}","{range:[]}","{range:[{},{}]}","{range:{min:[{value:0}],max:[{value:6}]}}","{range:{min:[{value:true}],max:[{value:5}]}}","{range:{min:[{value:0,unit:'degrees'}],max:[{value:5}]}}","{range:{min:[{value:0}],max:[{value:5}],increment:[{value:0}]}}","{range:{min:[{value:0}],max:[{value:5}],increment:[{value:0.5}]}}","{range:{mode:'cool',min:[{value:0}],max:[{value:5}]}}","{intValues:[0,true]}","{intValues:[0,6]}","{intValues:[0,0]}","{intValues:[]}","{intValues:'0,5'}","{intValues:['0',5]}"};
        for(String shape:shapes){Profile p=profile();JSONObject a=p.attribute(Swing.VERTICAL);a.remove("range");JSONObject replacement=new JSONObject(shape);for(Iterator<String> keys=replacement.keys();keys.hasNext();){String key=keys.next();a.put(key,replacement.get(key));}assertTrue(shape,Swing.positions(p,Swing.VERTICAL).isEmpty());rejects(p,state(),Swing.VERTICAL,3);}
    }
    @Test public void singletonRangeAndDefaultIntegerIncrementAreSupported()throws Exception{Profile p=profile();JSONObject r=range(0,5,1);r.remove("increment");p.attribute(Swing.VERTICAL).put("range",new JSONArray().put(r));assertEquals(List.of(0,1,2,3,4,5),Swing.positions(p,Swing.VERTICAL));}
    @Test public void invalidRequestedTypesAndOutOfRangeCodesAreRejected()throws Exception{for(Object value:new Object[]{-1,6,true,false,2.0,2.5,"2","auto","left",Long.valueOf(2)})rejects(profile(),state(),Swing.VERTICAL,value);}
    @Test public void unknownModelsAndPartnerRoutesCannotWriteSwing()throws Exception{
        Profile p=profile();p.device.put("modelId","unknown");rejects(p,state(),Swing.VERTICAL,2);p=profile();p.raw.put("modelId","unknown");rejects(p,state(),Swing.VERTICAL,2);
        for(String field:new String[]{"thirdPartyService","parentDeviceId"}){p=profile();p.device.put(field,"synthetic-partner");rejects(p,state(),Swing.VERTICAL,2);p=profile();p.raw.put(field,"synthetic-partner");rejects(p,state(),Swing.HORIZONTAL,2);}
        p=profile();p.device.put("category","ODMIRB-AC");rejects(p,state(),Swing.VERTICAL,2);assertFalse(new Profile(p.raw).supports(Swing.VERTICAL));
    }
    @Test public void reservedOrCollidingKeysAndDuplicateAxesAreRejected()throws Exception{for(String key:new String[]{"cnt","sid","ki","deviceId","ps","achs",""}){Profile p=profile();p.attribute(Swing.VERTICAL).put("key",key);rejects(p,state(),Swing.VERTICAL,2);}Profile p=profile();p.raw.getJSONArray("controlCapabilities").put(new JSONObject().put("capability",Swing.VERTICAL).put("attributes",new JSONArray().put(p.attribute(Swing.VERTICAL))));assertFalse(p.supports(Swing.VERTICAL));}
    @Test public void missingOfflinePowerAndCleaningStatesFailClosed()throws Exception{
        Profile p=profile();for(String cap:new String[]{Swing.VERTICAL,Swing.HORIZONTAL}){
            rejects(p,state().put("onlineStatus",false),cap,2);JSONObject s=state();s.remove("onlineStatus");rejects(p,s,cap,2);
            for(Object value:new Object[]{"off",JSONObject.NULL,"unknown"})rejects(p,state().put("ps",value),cap,2);
            for(Object value:new Object[]{"on",JSONObject.NULL,"unknown",false})rejects(p,state().put("acec",value),cap,2);
            s=state();s.remove("acec");rejects(p,s,cap,2);s=state();s.remove(p.key(cap));rejects(p,s,cap,2);rejects(p,state().put(p.key(cap),true),cap,2);
        }
    }
    @Test public void axesRemainAvailableInDryAndFanWhenGuardsPass()throws Exception{Profile p=profile();for(String mode:new String[]{"cool","auto","dry","fan"})for(String cap:new String[]{Swing.VERTICAL,Swing.HORIZONTAL})assertEquals("",p.blocked(state().put("acmd",mode),cap));}
    @Test public void firstReadWaitsThreeSecondsAndOnlySelectedAxisChanges()throws Exception{for(String cap:new String[]{Swing.VERTICAL,Swing.HORIZONTAL}){Fake f=new Fake();List<Long> waits=new ArrayList<>();List<String> progress=new ArrayList<>();CommandRunner.Result result=runner(f,waits,progress).execute(profile(),state(),cap,5);assertTrue(result.accepted());assertTrue(result.confirmed());assertFalse(result.physicalConfirmed());assertEquals(List.of(3000L),waits);assertEquals(1,f.sent.size());assertEquals(1,f.saved);assertEquals(1,result.observed().getInt(cap.equals(Swing.VERTICAL)?"achs":"acvs"));assertTrue(result.message().contains("Physical movement is not confirmed"));assertTrue(progress.stream().anyMatch(x->x.contains("accepted")));}}
    @Test public void unconfirmedSwingHasOneSendAndBoundedReadsWithoutChangingObserved()throws Exception{Fake f=new Fake();f.match=false;List<Long> waits=new ArrayList<>();CommandRunner.Result r=runner(f,waits,new ArrayList<>()).execute(profile(),state(),Swing.HORIZONTAL,5);assertTrue(r.accepted());assertFalse(r.confirmed());assertFalse(r.physicalConfirmed());assertEquals(0,r.completed());assertEquals(1,r.total());assertEquals(1,f.sent.size());assertEquals(5,f.reads);assertEquals(List.of(3000L,1200L,1800L,2400L,3000L),waits);assertEquals(1,r.observed().getInt("achs"));assertEquals(1,r.observed().getInt("acvs"));}
    @Test public void sendFailureDoesNotClaimAcceptanceOrReplay()throws Exception{Fake f=new Fake();f.failSend=true;CommandRunner.Result r=runner(f,new ArrayList<>(),new ArrayList<>()).execute(profile(),state(),Swing.VERTICAL,3);assertFalse(r.accepted());assertFalse(r.confirmed());assertEquals(1,f.sent.size());assertEquals(0,f.reads);assertEquals(1,r.observed().getInt("acvs"));}
    @Test public void failedOrExpiredReadRetainsPartialAcceptanceWithoutReplay()throws Exception{for(boolean expired:new boolean[]{false,true}){Fake f=new Fake();f.failRead=!expired;f.expire=expired;CommandRunner.Result r=runner(f,new ArrayList<>(),new ArrayList<>()).execute(profile(),state(),Swing.VERTICAL,3);assertTrue(r.accepted());assertFalse(r.confirmed());assertEquals(0,r.completed());assertEquals(1,r.total());assertEquals(1,f.sent.size());assertEquals(1,f.reads);assertEquals(1,r.observed().getInt("acvs"));}}
    @Test public void unsafeReadbackStopsEvenWhenRequestedCodeMatches()throws Exception{for(boolean cleaning:new boolean[]{false,true}){Fake f=new Fake();f.cleaning=cleaning;f.offline=!cleaning;CommandRunner.Result r=runner(f,new ArrayList<>(),new ArrayList<>()).execute(profile(),state(),Swing.VERTICAL,3);assertTrue(r.accepted());assertFalse(r.confirmed());assertEquals(1,f.reads);assertEquals(1,f.sent.size());}}
    @Test public void swingUiDraftNeverReplacesReportedValueOrOppositeAxis()throws Exception{Profile p=profile();JSONObject s=state();Swing.UiState before=Swing.uiState(p,s,Swing.VERTICAL,null,false,false);assertFalse(before.canApply());Swing.UiState draft=Swing.uiState(p,s,Swing.VERTICAL,5,false,false);assertTrue(draft.canApply());assertEquals(Integer.valueOf(1),draft.observedCode());assertEquals(Integer.valueOf(5),draft.draft());assertEquals(1,s.getInt("acvs"));assertEquals(Integer.valueOf(1),Swing.uiState(p,s,Swing.HORIZONTAL,null,false,false).observedCode());assertNull(Swing.uiState(p,s,Swing.HORIZONTAL,null,false,false).draft());}
    @Test public void uiPendingAndModeDraftDisableApplyWithoutLosingSelection()throws Exception{Profile p=profile();for(boolean busy:new boolean[]{false,true}){Swing.UiState state=Swing.uiState(p,state(),Swing.HORIZONTAL,3,busy,!busy);assertFalse(state.canApply());assertEquals(Integer.valueOf(3),state.draft());assertEquals(Integer.valueOf(1),state.observedCode());assertFalse(state.reason().isEmpty());}}
    @Test public void currentMatchingSelectionAndStaleUnsupportedDraftCannotApply()throws Exception{Profile p=profile();assertFalse(Swing.uiState(p,state(),Swing.HORIZONTAL,1,false,false).canApply());assertFalse(Swing.uiState(p,state(),Swing.HORIZONTAL,6,false,false).canApply());p.attribute(Swing.HORIZONTAL).put("intValues",new JSONArray("[0,1]"));assertFalse(Swing.uiState(p,state(),Swing.HORIZONTAL,3,false,false).canApply());}
    @Test public void missingAndUnavailableUiStatesAreHonest()throws Exception{Profile p=profile();JSONObject s=state();s.remove("achs");Swing.UiState ui=Swing.uiState(p,s,Swing.HORIZONTAL,3,false,false);assertNull(ui.observedCode());assertFalse(ui.canApply());assertTrue(ui.observedLabel().contains("Not reported"));p.attribute(Swing.HORIZONTAL).remove("range");ui=Swing.uiState(p,state(),Swing.HORIZONTAL,null,false,false);assertTrue(ui.choices().isEmpty());assertFalse(ui.reason().isEmpty());}
    @Test public void correctedLabelsRetainPerspectiveAndUnknowns()throws Exception{assertTrue(Swing.description(Swing.HORIZONTAL,1).contains("centered"));assertFalse(Swing.description(Swing.HORIZONTAL,3).contains("center"));assertTrue(Swing.description(Swing.HORIZONTAL,3).contains("left of 1"));assertFalse(Swing.description(Swing.HORIZONTAL,2).contains("leftmost"));assertTrue(Swing.guidance(Swing.HORIZONTAL).contains("facing the AC"));assertTrue(Swing.guidance(Swing.HORIZONTAL).contains("relative order of 2 and 3"));assertTrue(Swing.guidance(Swing.HORIZONTAL).contains("do not confirm"));assertTrue(Swing.description(Swing.VERTICAL,5).contains("Lowest tested"));}
}
